INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl004', 'NPL-004', 'ghk-cu', 'GHK-Cu', 'Copper(II) complex of glycyl-L-histidyl-L-lysine', '["Copper tripeptide-1","Cu-GHK"]', 'Metal-peptide complexes', '89030-95-5', '[]', 'GHK', 'Gly-His-Lys', 'C14H22CuN6O4', '401.91 g/mol', NULL, NULL, NULL, '71587328', 'Greater than or equal to 98% by HPLC', 'Blue to purple solid', 'Copper(II) complex, 1:1', '[]', 'Minus 20 C', 'Prepare fresh in aqueous buffer', 'Refer to the lot certificate', 'Ambient', 'available', 'The 1:1 copper(II) coordination complex of the tripeptide Gly-His-Lys. Supplied as a blue to purple solid. Molecular formulae in circulation for this complex differ by ligand protonation state; the value shown is the commercial consensus used by Cayman Chemical and MedChemExpress.', '["CAS 89030-95-5 and PubChem CID 71587328 verified.","Molecular formula is unsettled: four values are in circulation (401.91, 402.92, 403.92 and 400.90 g/mol) differing in ligand protonation. C14H22CuN6O4 at 401.91 is used by both Cayman 28259 and MedChemExpress HY-P0063 and is adopted here. No InChI Key is published because the structure is not settled.","Suppliers disagree on hazard classification: Cayman 28259 does not classify; MedChemExpress HY-P0063 assigns Warning with H302, H315, H319 and H335. The SDS issued with the supplied lot governs.","CAS 300801-03-0 (GHK-Cu acetate) is ambiguous - PubChem maps it to several structures including the 2:1 bis complex. Not used.","MilliporeSigma does not carry this compound.","Appearance verified as blue to purple. Not a white powder."]', 1, '/products/ghk-cu.png', 0, 'published', NULL, 40, 'seed');
