INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl005', 'NPL-005', 'selank', 'Selank', 'L-threonyl-L-lysyl-L-prolyl-L-arginyl-L-prolylglycyl-L-proline', '["TP-7"]', 'Peptides', '129954-34-3', '[{"form":"Monoacetate salt","cas":"2703745-90-6"}]', 'TKPRPGP', 'Thr-Lys-Pro-Arg-Pro-Gly-Pro', 'C33H57N11O9', '751.9 g/mol', NULL, NULL, NULL, NULL, 'Greater than or equal to 98% by HPLC', 'Solid', 'Monoacetate salt (C35H61N11O11, 811.9 g/mol) supplied under CAS 2703745-90-6. The diacetate is supplied under the free-base registry number', '[]', 'Minus 20 C', 'Prepare fresh; store aliquots at minus 20 C', 'Refer to the lot certificate', 'Ambient', 'limited', 'A synthetic heptapeptide of sequence TKPRPGP. Supplied lyophilised. Identity confirmed by mass spectrometry, purity determined by reversed-phase HPLC against the lot certificate. No USP or NF monograph exists for this substance.', '["CAS 129954-34-3, sequence, formula and molecular weight verified.","The monoacetate has its own registry number, 2703745-90-6 (C35H61N11O11, 811.9 g/mol). The diacetate does not - suppliers reuse the free-base CAS.","Cayman catalog 27720. MedChemExpress HY-105042.","MilliporeSigma listing unconfirmed."]', 1, '/products/selank.png', 0, 'published', NULL, 50, 'seed');
